import java.io.BufferedReader;import java.io.InputStreamReader;import java.util.StringTokenizer;public class TestClass {public static void main(String[] args) throws Exception {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));String line1 = br.readLine();if (line1 == null) return;StringTokenizer st1 = new StringTokenizer(line1);int N = Integer.parseInt(st1.nextToken());int K = Integer.parseInt(st1.nextToken());long[] arr = new long[N];StringTokenizer st2 = new StringTokenizer(br.readLine());for (int i = 0; i < N; i++) {arr[i] = Long.parseLong(st2.nextToken());}long[] prefixSum = new long[K + 1];long[] suffixSum = new long[K + 1];for (int i = 0; i < K; i++) {prefixSum[i + 1] = prefixSum[i] + arr[i];}for (int i = 0; i < K; i++) {suffixSum[i + 1] = suffixSum[i] + arr[N - 1 - i];}long maxSum = 0;for (int i = 0; i <= K; i++) {long currentSum = prefixSum[i] + suffixSum[K - i];if (i == 0) {maxSum = currentSum;} else {if (currentSum > maxSum) {maxSum = currentSum;}}}System.out.println(maxSum);}}